import csv
import json
from datetime import timedelta

# Load drivers data
with open('json/drivers.json', 'r') as f:
    drivers_data = json.load(f)

drivers = {d['driverId']: d for d in drivers_data['records']}

# Function to convert time string (MM:SS.mmm) to seconds
def time_to_seconds(time_str):
    if not time_str or time_str == '\\N':
        return None
    try:
        parts = time_str.split(':')
        if len(parts) == 2:
            return int(parts[0]) * 60 + float(parts[1])
        return float(time_str)
    except:
        return None

# Read qualifying data for race 19
best_time = None
best_driver = None
with open('csv/qualifying.csv', 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        if int(row['raceId']) == 19:
            q2_sec = time_to_seconds(row['q2'])
            if q2_sec is not None:
                if best_time is None or q2_sec < best_time:
                    best_time = q2_sec
                    best_driver = drivers[int(row['driverId'])]
                    best_raw_q2 = row['q2']

print(f"Driver: {best_driver['forename']} {best_driver['surname']}")
print(f"Driver ID: {best_driver['driverId']}")
print(f"Best Q2 time: {best_raw_q2}")
print(f"In seconds: {best_time}")
print(f"Surname: {best_driver['surname']}")
